function modelChoiceOptions(choices,current=studio?.config){return choices.map(m=>{const contract=studioModelContract(m),selected=current?.model===m.id&&(current.platformId===m.platformId||!current.platformId&&current.baseUrl===m.baseUrl);return `<option value="${esc(studioModelChoiceKey(m))}" ${selected?'selected':''} ${contract.supported?'':'disabled'}>${esc(m.display)}${contract.supported?'':' · 接口待核实'}</option>`}).join('');}
function renderStudioServiceSelector(){const choices=modelChoices(),supported=choices.filter(m=>studioModelContract(m).supported);return field('模型服务',`<select id="studio-service-model" aria-label="已登记的${studio.mode==='image'?'图片':'视频'}模型"><option value="">${supported.length?'选择模型…':'暂无已适配接口的模型'}</option>${modelChoiceOptions(choices)}</select><button id="refresh-studio-catalog" class="text-link">刷新服务目录</button>`,catalogStatus||`${choices.length} 个${studio.mode==='image'?'图片':'视频'}型号；目录与接口适配不代表账户有权限或已完成真实生成。`);}
function selectStudioServiceModel(key){const choice=findStudioModelChoice(modelChoices(),key);if(!choice)return;try{checkpoint();studio.config=applyStudioModelChoice(studio.config,choice);credentialMemory=isLocalStudioServiceTarget(studio)?'miao-local':'manual';keyMemory='';markDirty();renderAll();}catch(e){toast(e.message);}}
async function loadStudioCatalog({refresh=false}={}){try{const data=await call('/api/studio-catalog');apimartAvailable=data.apimartMaterials===true;savedPlatforms=data.platforms||[];discoveredByPlatform=data.discoveredByPlatform||{};catalogCredentialStatus=data.credentialStatus;if(refresh){for(const p of savedPlatforms){const target={mode:'image',config:{protocol:'studio',baseUrl:p.baseUrl}};if(!isLocalStudioServiceTarget(target)||!catalogCredentialStatus?.configured||catalogRefreshed.has(p.id))continue;catalogRefreshed.add(p.id);try{const result=await call('/api/studio-models',json('POST',{platformId:p.id,mode:studio?.mode||'video',credentialSource:'miao-local',credentialConsent:true,consent:true,apiKey:''}));discoveredByPlatform[p.id]=result.models||[];catalogStatus=result.note||'服务目录已更新；账户权限与真实生成尚未验证。';}catch(e){catalogStatus=`目录刷新失败：${e.message}。已保存型号仍保留；不会自动重试。`;}}}if(studio&&selectedNode==='config')renderInspector();}catch(e){catalogStatus=`本机服务目录暂不可用：${e.message}`;if(studio&&selectedNode==='config')renderInspector();}}
let spacePanDown=false;
