const call=async(url,opts={})=>{const r=await nativeMediaPageSession.fetch(url,opts);let data={};try{data=await r.json()}catch{}if(!r.ok){const e=new Error(data.error||`请求失败 (${r.status})`);e.status=r.status;throw e}publishTaskSnapshot(data);return data};
function toast(s){const t=$('#toast');t.textContent=s;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),3300)}
function clone(x){return JSON.parse(JSON.stringify(x))}
function initialStudio(){return {id:'',name:'未命名项目',revision:0,mode:'video',prompt:'',config:clone(DEFAULT_CONFIG),references:[],nodes:clone(DEFAULT_NODES),viewport:{x:0,y:0,zoom:1},view:'canvas',createdAt:new Date().toISOString(),updatedAt:new Date().toISOString()}}
function checkpoint(){if(!studio)return;undoStack.push(clone(studio));if(undoStack.length>30)undoStack.shift();redoStack=[]}
function markDirty(){dirty=true;$('#save-indicator').textContent=stale?'版本冲突 · 点击保留为副本':'有未保存更改';clearTimeout(timer);if(!stale)timer=setTimeout(()=>saveStudio(),500);refreshPreview();}
async function saveStudio(){
 clearTimeout(timer);
 if(stale)return false;
 if(savePromise){const ok=await savePromise;if(!ok)return false;return dirty?saveStudio():true;}
 if(!studio?.id||!dirty)return true;
 const snap=clone(studio);dirty=false;$('#save-indicator').textContent='正在保存…';
 savePromise=(async()=>{try{
  const saved=await call(`/api/studios/${encodeURIComponent(snap.id)}`,json('PUT',snap));
  if(studio.id===snap.id){studio.revision=saved.revision;studio.updatedAt=saved.updatedAt;studio.projectRevision=saved.projectRevision;lastSaved=clone(saved);}
  $('#save-indicator').textContent=dirty?'有未保存更改':'已保存到本机工作区';
  const item=studios.find(p=>p.id===snap.id);if(item)item.name=snap.name;drawProjectSelect();return true;
 }catch(e){dirty=true;stale=e.status===409;
  $('#save-indicator').textContent=stale?'版本冲突 · 点击保留为副本':'保存失败 · 点击重试';
  if(stale)toast('其他窗口已更新。当前改动保留在本页，可保存为副本后继续。');else toast('保存失败，当前改动仍保留');return false;
 }finally{savePromise=null;}})();
 const ok=await savePromise;if(ok&&dirty)return saveStudio();return ok;
}
function setTheme(persist=false){theme=window.JingchangTheme?.set(theme,{persist})||theme;document.documentElement.dataset.theme=theme;document.querySelector('.studio').dataset.theme=theme;$('#theme-toggle').textContent=theme==='light'?'◐':'☼'}
window.addEventListener('jingchang:theme',event=>{theme=event.detail.theme;const toggle=$('#theme-toggle');if(toggle)toggle.textContent=theme==='light'?'◐':'☼'});
async function loadStudios(){studios=await call('/api/studios');drawProjectSelect()}
function drawProjectSelect(){const sel=$('#project-select');if(!studios.length){sel.innerHTML='<option>暂无项目</option>';return}sel.innerHTML=studios.map(p=>`<option value="${esc(p.id)}" ${p.id===studio?.id?'selected':''}>${esc(p.name)}</option>`).join('')}
async function openStudio(id){
 const sequence=++studioOpenSequence;clearTimeout(timer);if(studio&&(dirty||savePromise)&&!await saveStudio()){if(sequence!==studioOpenSequence)return false;drawProjectSelect();toast('当前改动尚未保存，已保留在原项目');return false;}
 if(sequence!==studioOpenSequence)return false;const next=await call(`/api/studios/${encodeURIComponent(id)}`);if(sequence!==studioOpenSequence)return false;clearTimeout(pollTimer);activeJob=null;pendingSubmission=null;
 keyMemory='';credentialMemory='manual';studio=next;studio.config={...clone(DEFAULT_CONFIG),...(studio.config||{})};studio.references||=[];
 studio.nodes=NODES.map((node,i)=>studio.nodes?.find(n=>n.id===node)||clone(DEFAULT_NODES[i]));studio.viewport||={x:0,y:0,zoom:1};
 undoStack=[];redoStack=[];dirty=false;stale=false;lastSaved=clone(studio);jobs=[];drawProjectSelect();renderAll();syncProjectLinks();
 history.replaceState(null,'',`/creation-studio.html?project=${encodeURIComponent(studio.id)}`);
 $('#save-indicator').textContent='已保存到本机工作区';await refreshJobs();return true;
}
function syncProjectLinks(){for(const a of $$('[data-project-link]'))a.href=studio?.projectId?`/?project=${encodeURIComponent(studio.projectId)}`:'/';}
async function preserveConflict(){
 if(!stale){await saveStudio();return;}
 const draft=clone(studio);const copy=await call('/api/studios',json('POST',{name:draft.name+' · 创作改动副本',mode:draft.mode}));
 const saved=await call(`/api/studios/${copy.id}`,json('PUT',{...draft,id:copy.id,projectId:copy.projectId,projectRevision:copy.projectRevision,revision:copy.revision,name:copy.name}));
 dirty=false;stale=false;await loadStudios();await openStudio(saved.id);toast('创作参数已另存新项目，原项目与其他窗口改动均保留');
}
async function createStudio(){try{if(studio&&(dirty||savePromise)&&!await saveStudio()){toast('请先保存当前改动');return;}const p=await call('/api/studios',json('POST',{name:'未命名项目'}));await loadStudios();await openStudio(p.id);toast('已新建项目与关联画布')}catch(e){toast(e.message)}}
function safeText(v){return String(v??'')}
function mediaHtml(ref,small=false){const asset=ref.assetId?assets.find(a=>a.id===ref.assetId):null;const url=asset?`/media/${encodeURIComponent(asset.id)}`:ref.url||'';const type=asset?.type||ref.type||'';if(!asset)return `<span class="external-placeholder" title="外链仅在授权提交后读取">↗ URL</span>`;if(type.startsWith('image/'))return `<img src="${esc(url)}" alt="${esc(asset?.name||ref.url||'参考图片')}" ${small?'':'loading="lazy"'}>`;if(type.startsWith('video/'))return `<video src="${esc(url)}" ${small?'':'preload="metadata"'}></video>`;if(type.startsWith('audio/'))return `<span>♫</span>`;return `<span>${ref.assetId?'▧':'↗'}</span>`}
function refType(ref){return assets.find(a=>a.id===ref.assetId)?.type||ref.type||''}
function limitsFor(type){const refs=studio.references;if(refs.length>=studioReferenceLimit(studio))return false;return type.startsWith('image/')?refs.filter(r=>refType(r).startsWith('image/')).length<studioImageReferenceLimit(studio):type.startsWith('video/')?refs.filter(r=>refType(r).startsWith('video/')).length<3:type.startsWith('audio/')?refs.filter(r=>refType(r).startsWith('audio/')).length<studioAudioReferenceLimit(studio):false}
function countRefs(){return studio.references.length}
function refreshPreview(){if(!studio)return;$('#preview-prompt').textContent=studio.prompt.trim()||'描述你想要的画面…';$('#reference-count').textContent=`${countRefs()} 项`;$('#preview-references').innerHTML=studio.references.slice(0,4).map(r=>mediaHtml(r,true)).join('')||'<span class="empty-reference">＋</span><span>拖入图片、视频或音频</span>';let c=studio.config;$('#preview-config').textContent=isJimengStudio(studio)?`${studio.mode==='video'?c.resolution:c.imageResolution} · ${c.ratio} · ${studio.mode==='video'?c.duration+'秒':c.count+'张'} · 即梦`:studio.mode==='video'?`${c.resolution} · ${c.ratio} · ${c.duration} 秒`:(c.protocol==='midjourney'?`${MJ_MODES[c.mjMode]||'Midjourney'} · ${c.mjSize||c.ratio} · 1次操作`:['gemini','apimart'].includes(c.protocol)?`${c.protocol==='gemini'?'模型默认清晰度':c.imageResolution} · ${c.ratio} · ${c.count} 张`:`${c.quality} · ${c.size} · ${c.count} 张`);$('#node-model').textContent=c.model||(isJimengStudio(studio)?'命令默认':'选择模型');drawWire();updateEstimate();}
function estimatedCost(){const c=studio?.config||DEFAULT_CONFIG;return Math.max(0,Number(c.unitPrice)||0)*(studio?.mode==='image'?Number(c.count||1):Number(c.duration||4));}
function currencySymbol(){return studio?.config.currency==='USD'?'$':'¥';}
function updateEstimate(){const cost=estimatedCost(),label=cost>0?`${currencySymbol()}${cost.toFixed(2)}`:'尚未填写单价';$('#cost-estimate').textContent=label;$('#mobile-cost').textContent=cost>0?`估算 ${label}`:label;}
function applyViewport(){const v=studio.viewport;$('#canvas-world').style.transform=`translate(${v.x}px,${v.y}px) scale(${v.zoom})`;$('#zoom-label').textContent=`${Math.round(v.zoom*100)}%`;drawWire()}
function drawWire(){const svg=$('#node-wires');if(!svg||!studio)return;const nodes=studio.nodes;svg.innerHTML='';for(let i=0;i<nodes.length-1;i++){const a=nodes[i],b=nodes[i+1],x1=a.x+($(`[data-node="${a.id}"]`)?.offsetWidth||202),y1=a.y+57,x2=b.x,y2=b.y+57,mid=(x1+x2)/2;svg.insertAdjacentHTML('beforeend',`<path d="M${x1} ${y1} C${mid} ${y1},${mid} ${y2},${x2} ${y2}" fill="none" stroke="var(--line-strong)" stroke-width="1.5"/><circle cx="${x1}" cy="${y1}" r="2.3" fill="#91a985"/><circle cx="${x2}" cy="${y2}" r="2.3" fill="#91a985"/>`)}drawMinimap();}
function updateModeLabels(){const image=studio.mode==='image',labels=image?['文生图片','参考图生成','多图参考']:['文生视频','图生视频','多参考整理'];$$('.template-card').forEach((button,i)=>{button.querySelector('b').textContent=labels[i];});$('#canvas-title').textContent=studio.name;$('#canvas-context').textContent=image?'图片创作 · 从描述、参考到可复用的画面':'视频创作 · 从构思、镜头到动态画面';}
function renderAll(){updateModeLabels();renderInspector();renderLibrary();renderCanvas();refreshPreview();applyViewport();$('#mode-video').classList.toggle('active',studio.mode==='video');$('#mode-image').classList.toggle('active',studio.mode==='image');$('#view-canvas').classList.toggle('active',studio.view==='canvas');$('#view-list').classList.toggle('active',studio.view==='list');$('#canvas-world').hidden=studio.view==='list';$('#canvas-list').hidden=studio.view!=='list'}
function renderCanvas(){const world=$('#canvas-world');world.querySelectorAll('.workflow-node').forEach(el=>{const id=el.dataset.node,n=studio.nodes.find(x=>x.id===id);el.style.left=`${n.x}px`;el.style.top=`${n.y}px`;el.classList.toggle('active-node',id===selectedNode)});renderList()}
function renderList(){$('#canvas-list').innerHTML=NODES.map((id,i)=>`<div class="list-row" data-list-node="${id}"><span class="list-step">0${i+1}</span><div><b>${TITLES[id]}</b><small>${id==='prompt'?esc(studio.prompt||'尚未填写提示词'):id==='references'?`${countRefs()} 项参考素材`:id==='config'?esc(studio.config.model):id==='generate'?'检查数据发送与预算授权':'查看与下载生成结果'}</small></div><span style="margin-left:auto;color:var(--muted)">›</span></div>`).join('')}
