function selectOptions(name,values,current,labels={}){return `<select data-config="${name}">${values.map(v=>`<option value="${v}" ${current===v?'selected':''}>${esc(labels[v]||v)}</option>`).join('')}</select>`}
function renderInspector(){if(!studio)return;const id=selectedNode||'prompt';$('#inspector-heading').textContent=TITLES[id];$('#inspector-subtitle').textContent=({prompt:'清楚描述你希望看到的画面',references:'添加或管理创作参考素材',config:'选择模型与输出规格',generate:'确认数据去向与预算后开始',output:'预览、下载或复用任务结果'})[id];const host=$('#inspector');if(id==='prompt'){host.innerHTML=`${field('创作提示词',`<textarea id="prompt-input" maxlength="${isJimengStudio(studio)?20000:5000}" placeholder="例如：清晨薄雾中的江南水乡，镜头缓缓掠过石桥与河面，电影质感，柔和的暖色调……">${esc(studio.prompt)}</textarea>`,`${isJimengStudio(studio)?'最多 20,000 字':'最多 5,000 字'}。建议描述主体、环境、镜头运动和氛围。`)}<div class="character-count"><span>支持中文与自然语言</span><span><b id="prompt-count">${studio.prompt.length}</b> / ${isJimengStudio(studio)?'20,000':'5,000'}</span></div><div class="subheading">快速模板</div><div class="segmented template-inline"><button data-template="text" class="${modeTemplate==='text'?'active':''}">${studio.mode==='image'?'文生图片':'文生视频'}</button><button data-template="image" class="${modeTemplate==='image'?'active':''}">${studio.mode==='image'?'参考图生成':'图生视频'}</button><button data-template="multi" class="${modeTemplate==='multi'?'active':''}">多参考</button></div><div class="info-box">模板只切换创作方式提示，不会清除已有提示词或参考素材。</div>`}else if(id==='references'){host.innerHTML=`<div class="inspector-section"><label>添加参考素材</label><div class="ref-drop" id="ref-drop"><strong>点击选择文件，或将素材拖到这里</strong><span>图片最多 ${studioImageReferenceLimit(studio)} · 视频最多 3 · 音频最多 ${studioAudioReferenceLimit(studio)}</span></div><div class="url-add">${(isArkMultimodal(studio)||isApimartMultimodal(studio))?`<select id="reference-url-type" aria-label="外部参考类型"><option value="image/png">图片</option><option value="video/mp4">视频 MP4/MOV</option><option value="audio/wav">音频 WAV</option><option value="audio/mpeg">音频 MP3</option></select>`:''}<input id="reference-url" type="text" placeholder="${(isArkMultimodal(studio)||isApimartMultimodal(studio))?'https:// 或 asset:// 素材编号':'粘贴 https 图片链接'}"><button id="add-url-ref">添加</button></div><div class="field-help">${(isArkMultimodal(studio)||isApimartMultimodal(studio))?'多素材参考：图片与音频可用本机文件；视频需公网 HTTPS 或平台 asset:// 编号。地址的格式、时长和访问权限交由平台检查，添加时不读取外链。音频单段2–15秒，合计15秒；视频单段2–15秒，合计15秒。':'图片链接必须使用 HTTPS；添加时不会请求外部链接，仅在授权提交后读取。'}移除仅会从本项目引用中取消，不会删除素材文件。</div></div><div class="ref-list">${studio.references.map((r,i)=>{const a=assets.find(x=>x.id===r.assetId);return `<div class="ref-row"><div class="ref-thumb">${mediaHtml(r,true)}</div><div class="ref-info"><b>${esc(a?.name||r.url||'参考素材')}</b><small>${esc(refType(r)||'未知类型')}</small></div><button data-remove-ref="${i}" title="移除引用">×</button></div>`}).join('')||'<div class="empty-state"><strong>还没有参考素材</strong>添加图片、视频或音频来引导生成</div>'}</div>`}else if(id==='config'){host.innerHTML='<button id="choose-jimeng" class="outline-button">使用本机即梦</button><button id="jimeng-account" class="outline-button">即梦登录与积分</button>'+renderStudioServiceSelector()+(studio.mode==='video'?renderVideoConfig():renderImageConfig())}else if(id==='generate'){host.innerHTML=`<div class="info-box">镜场是你的自有本地工作区。提交后，提示词与所选参考素材将发送至你填写的上游 API。</div>${field('本次模型',`<input type="text" data-config="model" value="${esc(studio.config.model)}" placeholder="填写上游模型 ID">`,`可填写自定义模型；模型可用性与价格以你的上游服务为准。`)}${field('API 目的地',`<input type="text" readonly value="${esc(studio.config.baseUrl||'尚未设置连接地址')}">`)}${field('请求数量',`<input type="number" readonly value="1">`,`本次点击最多提交 1 次；如果状态不确定，请先查询历史任务，不要重复提交。`)}<button class="outline-button" id="connect-from-generate" style="width:100%">打开连接设置</button>`}else host.innerHTML=`<div id="latest-output">${renderLatestOutput()}</div><button class="outline-button" id="refresh-history" style="width:100%;margin-top:12px">刷新历史任务</button>`;if(id==='generate'&&isJimengStudio(studio))host.innerHTML='<div class="info-box">本机即梦使用已有登录，身份和积分未检查。运行前会预览实际命令、文字和本机文件，并分别确认生成预算与原编号查询范围；无需API密钥。</div>';if(id==='references'&&isJimengStudio(studio)){const urls=host.querySelector('.url-add');if(urls)urls.hidden=true;const help=host.querySelector('.field-help');if(help)help.textContent='即梦只使用本机素材；按列表顺序传递，首尾帧第1张为首帧、第2张为尾帧。大文件可先通过主画布素材导入，再选用本机素材。';}host.querySelector('#jimeng-account')?.addEventListener('click',async()=>{try{if(!await saveStudio())return;location.href='/jimeng-account.html?project='+encodeURIComponent(studio.projectId);}catch(error){toast(error.message);}});host.querySelector('#choose-jimeng')?.addEventListener('click',()=>{checkpoint();studio.config=jimengStudioDefaults(studio.mode);keyMemory='';credentialMemory='manual';markDirty();renderAll();});const jimengFields=host.querySelector('[data-jimeng-fields]');if(jimengFields)jimengFields.onchange=e=>{try{checkpoint();if(e.target.name==='jt-command'){studio.config=jimengChangedCommand(studio.config,studio.mode,e.target.value);markDirty();renderAll();}else{studio.config=readJimengStudioFields(host,studio.mode);markDirty();refreshPreview();}}catch(error){toast(error.message);}};host.querySelectorAll('[data-config]').forEach(el=>el.addEventListener('change',configChanged));const p=host.querySelector('#prompt-input');if(p){p.addEventListener('input',()=>{checkpoint();studio.prompt=p.value;$('#prompt-count').textContent=p.value.length;markDirty()})}host.querySelector('#ref-drop')?.addEventListener('click',()=>$('#file-picker').click());host.querySelector('#add-url-ref')?.addEventListener('click',addUrlReference);host.querySelector('[data-config="model"]')?.addEventListener('input',()=>{studio.config.model=host.querySelector('[data-config="model"]').value;delete studio.config.platformId;markDirty()});host.querySelector('#connect-from-generate')?.addEventListener('click',connectDialog);host.querySelector('#refresh-history')?.addEventListener('click',refreshJobs)}
function renderVideoConfig(){const c=studio.config;if(isJimengStudio(studio))return jimengStudioFields(studio,esc);if(c.protocol==='ark')return `${field('参考模式',selectOptions('arkReferenceMode',['frames','multimodal'],c.arkReferenceMode||'frames',{frames:'首帧 / 首尾帧（保留原项目行为）',multimodal:'Seedance 2.0 多素材参考'}))}<div class="info-box">${(isArkMultimodal(studio)||isApimartMultimodal(studio))?'最多9张图片、3段视频、3段音频。图片使用 reference_image，视频使用 reference_video，音频使用 reference_audio，不与首尾帧角色混用。至少一张图或一段视频；不能仅用音频。平台 ep- 接入点需对应 Seedance 2.0 系列。':'第一张参考为首帧，第二张为尾帧。支持纯文字、单图、首尾帧。'}</div><div class="form-grid">${field('模型 ID / 接入点',`<input type="text" data-config="model" value="${esc(c.model)}" placeholder="doubao-seedance-2-0-… 或 ep-…">`)}${field('清晰度',selectOptions('resolution',['480p','720p','1080p'],c.resolution))}${field('画面比例',selectOptions('ratio',['16:9','9:16','1:1','4:3','3:4','21:9'],c.ratio))}${field('输出时长（秒）',`<input type="number" data-config="duration" min="4" max="15" step="1" value="${c.duration}">`)}<label class="toggle-row">生成音频 <input type="checkbox" data-config="generateAudio" ${c.generateAudio?'checked':''}></label></div><p class="field-help">切换模式保留素材引用；不支持的引用会在提交前明确提示。此处的“生成音频”控制输出声音，参考音频会发送所选原文件。</p>`;if(c.protocol==='apimart')return `${field('参考模式',selectOptions('apimartReferenceMode',['frames','multimodal'],c.apimartReferenceMode||'frames',{frames:'首帧 / 首尾帧（保留原行为）',multimodal:'多素材 / asset://可信素材'}))}<div class="info-box">${isApimartMultimodal(studio)?'多素材模式：最多9图、3视频、3音频，公网HTTPS或审核后的asset://。视频和音频各自总时长最多15秒，外部内容由平台检查。':'首尾帧模式：最多两张公网图片，不混合音视频。'} Seedance 2.0：5–15秒。注册素材和生成视频分开确认；不会自动上传本机文件。</div><div class="form-grid">${field('模型',selectOptions('model',['doubao-seedance-2.0','doubao-seedance-2.0-fast'],c.model))}${field('清晰度',selectOptions('resolution',['480p','720p'],c.resolution))}${field('画面比例',selectOptions('ratio',['16:9','9:16','1:1','4:3','3:4','21:9'],c.ratio))}${field('时长（秒）',`<input type="number" data-config="duration" min="5" max="15" value="${c.duration}">`)}<label class="toggle-row">生成音频 <input type="checkbox" data-config="generateAudio" ${c.generateAudio?'checked':''}></label></div>`;return `${c.protocol==='ark'?'<div class="info-box">火山方舟：第一张参考为首帧，第二张为尾帧。支持文生视频、单图、首尾帧，不使用视频编辑或延长接口。</div>':''}<div class="form-grid">${field('模型',`<input type="text" data-config="model" value="${esc(c.model)}" placeholder="上游模型 ID">`)}${field('操作',selectOptions('operation',['generate','edit','extend'],c.operation,{generate:'生成',edit:'编辑',extend:'延长'}))}${field('清晰度',selectOptions('resolution',['480p','720p','1080p'],c.resolution))}${field('画面比例',selectOptions('ratio',['16:9','9:16','1:1','4:3','3:4','21:9'],c.ratio))}${field('时长（秒）',`<input type="number" data-config="duration" min="4" max="15" step="1" value="${Number(c.duration)||4}">`)}<div class="inspector-section"><label class="toggle-row">生成音频 <input type="checkbox" data-config="generateAudio" ${c.generateAudio?'checked':''}></label></div><div class="inspector-section span-2"><button id="discover-models" class="text-link">从连接地址拉取可用模型 ↗</button></div></div><div class="info-box">当前视频适配契约：videos/generations 提交与 videos/jobs 查询。生成支持文字或单张图；编辑 / 延长支持单段视频。请先核对服务商接口兼容性。</div>`}
function renderNativeImageConfig(){const c=studio.config,gemini=c.protocol==='gemini';return `<div class="info-box">${gemini?'Gemini 原生图片：文字生图或参考图编辑，单次返回一张图片。使用模型默认清晰度。':'APIMart 异步图片：当前支持 gpt-image-2 / gpt-image-2-ext，最多4张参考图。'}</div><div class="form-grid">${field('模型 ID',`<input type="text" data-config="model" value="${esc(c.model)}">`)}${field('画面比例',selectOptions('ratio',['16:9','9:16','1:1','4:3','3:4','21:9'],c.ratio))}${gemini?'':field('清晰度',selectOptions('imageResolution',['1k','2k','4k'],c.imageResolution||'1k'))+field('生成数量',selectOptions('count',['1','2','4'],String(c.count)))}<div class="inspector-section span-2"><button id="discover-models" class="text-link">从连接地址拉取可用模型 ↗</button></div></div>`}
function renderImageConfig(){if(isJimengStudio(studio))return jimengStudioFields(studio,esc);const c=studio.config,countChoices=[1,2,4].map(String);if(c.protocol==='midjourney')return `<div class="info-box">Midjourney异步操作 · 每次单独确认，不自动重复提交。局部重绘的两步请求分别授权。</div>${midjourneyFields(c,esc)}`;if(['gemini','apimart'].includes(c.protocol))return renderNativeImageConfig();if(c.protocol==='modelscope')return `<div class="info-box">ModelScope 异步单图 · 使用模型默认尺寸与质量。可在连接设置中填写 LoRA，支持1–3张参考图编辑，请选择支持图片编辑的模型。</div>${field('模型 ID','<input type="text" data-config="model" value="'+esc(c.model)+'">')}`;return `<div class="form-grid">${field('模型',`<input type="text" data-config="model" value="${esc(c.model)}" placeholder="上游模型 ID"><select id="model-select" style="margin-top:6px"><option value="">选择已发现模型…</option>${models.map(m=>`<option value="${esc(m.id)}" ${m.id===c.model?'selected':''}>${esc(modelDisplayName(m))}</option>`).join('')}</select>`)}${field('质量',selectOptions('quality',['auto','high','medium','low'],c.quality,{auto:'自动',high:'高',medium:'中',low:'低'}).replace('<select ',`<select ${c.imageAsync?'disabled':''} `))}${field('尺寸',selectOptions('size',['auto','1024x1024','1536x1024','1024x1536'],c.size,{auto:'自动', '1024x1024':'1024 × 1024','1536x1024':'1536 × 1024','1024x1536':'1024 × 1536'}))}${field('生成数量',`<select data-config="count">${countChoices.map(v=>`<option value="${v}" ${String(c.count)===v?'selected':''} ${c.imageAsync&&v!=='1'?'disabled':''}>${v}</option>`).join('')}</select>`)}<div class="inspector-section span-2"><label class="toggle-row">透明背景 <input type="checkbox" data-config="transparent" ${c.transparent?'checked':''} ${c.imageAsync?'disabled':''}></label><label class="toggle-row">异步图片任务 <input type="checkbox" data-config="imageAsync" ${c.imageAsync?'checked':''}></label></div><div class="inspector-section span-2"><button id="discover-models" class="text-link">从连接地址拉取可用模型 ↗</button></div></div>${c.imageAsync?'<div class="warning-box">异步图片任务仅支持纯文字、单张、自动质量且无透明背景。开启后数量自动设为 1、透明背景关闭、质量设为自动。已有参考素材会保留，但需先从本次引用中移除才能提交。</div>':'<div class="info-box">实际支持的质量、尺寸与透明背景能力由所选上游模型决定。</div>'}`}
function configChanged(e){const el=e.currentTarget||e.target,name=el.dataset.config;if(!name)return;checkpoint();let val=el.type==='checkbox'?el.checked:el.type==='number'?Number(el.value):el.value;if(name==='duration')val=Math.max(4,Math.min(15,val||4));if(name==='count')val=Number(val);studio.config[name]=val;if(name==='model')delete studio.config.platformId;if(name==='imageAsync'&&val){studio.config.count=1;studio.config.transparent=false;studio.config.quality='auto'}refreshPreview();markDirty();renderInspector()}
function renderLibrary(){const el=$('#library-content');if(library==='assets'){el.innerHTML=`<div class="library-toolbar"><input class="library-search" id="asset-search" placeholder="搜索素材"><button class="small-add" id="upload-assets">＋ 导入</button><button class="small-add" id="open-ark-assets">火山素材库</button>${apimartAvailable?'<button class="small-add" id="open-apimart-materials">APIMart素材</button>':''}<button class="small-add" id="open-public-media">公网链接</button></div>${assets.length?assets.map(a=>`<div class="asset-item" data-asset-item="${esc(a.id)}"><div class="asset-thumb">${mediaHtml({assetId:a.id},true)}</div><div class="asset-details"><b>${esc(a.name)}</b><small>${esc(a.type)} · ${formatSize(a.size)}</small></div><button class="asset-use" data-use-asset="${esc(a.id)}">引用</button></div>`).join(''):'<div class="empty-state"><strong>素材库还是空的</strong>导入文件后可在多个创作中引用</div>'}`}else{el.innerHTML=jobs.length?jobs.map(j=>`<div class="history-item" data-job="${esc(j.id)}"><span class="history-status ${esc(j.status)}"></span><div class="history-details"><b>${esc(j.input?.studio?.prompt||j.message||j.id)}</b><small>${statusLabel(j.status)} · ${dateLabel(j.createdAt)}</small></div><button class="history-open" data-open-job="${esc(j.id)}">查看</button></div>`).join(''):'<div class="empty-state"><strong>还没有历史任务</strong>本项目提交的任务会显示在这里</div>'}}
function formatSize(n=0){return n>1024*1024?`${(n/1024/1024).toFixed(1)} MB`:`${Math.max(1,Math.round(n/1024))} KB`}
function statusLabel(s){return ({queued:'排队中',running:'生成中',completed:'已完成',failed:'失败',interrupted:'已中断',cancelled:'已停止',awaiting_input:'等待重绘补参',uncertain:'状态待确认'})[s]||s||'未知'}
function dateLabel(s){return s?new Date(s).toLocaleString('zh-CN',{month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit'}):''}
function renderLatestOutput(){const j=jobs.find(x=>x.status==='completed'&&x.assets?.length);if(!j)return '<div class="empty-state"><strong>暂无生成结果</strong>完成任务后可在这里预览并下载</div>';return j.assets.map(a=>`<div class="job-result">${a.type?.startsWith('image/')?`<img src="/media/${encodeURIComponent(a.id)}" alt="${esc(a.name)}">`:a.type?.startsWith('video/')?`<video controls src="/media/${encodeURIComponent(a.id)}"></video>`:`<audio controls src="/media/${encodeURIComponent(a.id)}"></audio>`}<a class="download-button" href="/media/${encodeURIComponent(a.id)}" download="${esc(a.name)}">下载 ${esc(a.name)}</a><button class="text-link" data-reuse-job="${esc(j.id)}">复用此任务参数</button><button class="text-link" data-apply-job="${esc(j.id)}">查看 / 放入画布</button></div>`).join('')}
async function loadAssets(){assets=await call('/api/assets');renderLibrary()}
async function refreshJobs(){if(!studio?.id)return;const id=studio.id,next=await call(`/api/studios/${encodeURIComponent(id)}/jobs`);if(studio.id!==id)return;jobs=next;renderLibrary();if(selectedNode==='output')renderInspector();const latest=jobs[0];$('#output-status').textContent=latest?statusLabel(latest.status):'待生成';const result=jobs.find(j=>j.status==='completed'&&j.assets?.length);$('#preview-output').innerHTML=result?`<span class="output-symbol">✓</span><span>${result.assets.length} 项结果已保存到本机<br>打开输出预览并放入画布</span>`:'<span class="output-symbol">▱</span><span>生成结果将在这里展示</span>';}
function setLibrary(which){library=which;$$('.library-tab').forEach(b=>b.classList.toggle('active',b.dataset.library===which));renderLibrary();if(which==='history')refreshJobs().catch(e=>toast(e.message))}
async function uploadFiles(files){for(const f of files){if(!['image/','video/','audio/'].some(t=>f.type.startsWith(t))){toast(`${f.name} 格式不支持`);continue}const cap=f.type.startsWith('image/')?10*1024*1024:f.type.startsWith('video/')?32*1024*1024:20*1024*1024;if(f.size>cap){toast(`${f.name} 超过${f.type.startsWith('image/')?'10 MB':f.type.startsWith('video/')?'32 MB':'20 MB'}上限`);continue}if(!limitsFor(f.type)){toast(`该类型参考素材已达到上限`);continue}try{const a=await call('/api/assets?name='+encodeURIComponent(f.name),{method:'POST',headers:{'Content-Type':f.type||'application/octet-stream'},body:await f.arrayBuffer()});assets.unshift(a);checkpoint();studio.references.push({assetId:a.id});markDirty()}catch(e){toast(`${f.name}：${e.message}`)}}renderAll()}
function addUrlReference(){const input=$('#reference-url'),url=input?.value.trim(),type=$('#reference-url-type')?.value||'image/png';if(!url)return;if(!limitsFor(type)){toast('该类型参考素材已达到当前模式上限');return}try{const u=new URL(url),asset=(isArkMultimodal(studio)||isApimartMultimodal(studio))&&/^asset:\/\/[A-Za-z0-9_-]{1,128}$/.test(url);if(!asset&&(u.protocol!=='https:'||u.username||u.password||u.search||u.hash))throw Error('请输入公网 HTTPS 地址或当前平台素材编号，不接受登录信息或查询参数');if(studio.references.some(r=>r.url===url))throw Error('此素材地址已在参考中');checkpoint();studio.references.push({url:asset?url:u.href,type});input.value='';markDirty();renderAll()}catch(e){toast(e.message||'参考地址无效')}}
function removeReference(index){checkpoint();studio.references.splice(index,1);markDirty();renderAll()}
function useAsset(id){const a=assets.find(x=>x.id===id);if(!a)return;if(!limitsFor(a.type)){toast('此类型参考素材已达到上限');return}checkpoint();studio.references.push({assetId:id});markDirty();renderAll();toast('已引用素材；原文件保留在素材库')}
function selectNode(id){selectedNode=id;renderInspector();renderCanvas();if(innerWidth<=700)$('#right-panel').classList.add('open')}
function setTemplate(name){modeTemplate=name;$$('.template-card').forEach(b=>b.classList.toggle('selected',b.dataset.template===name));selectNode(name==='text'?'prompt':'references');const info=name==='text'?'填写主体、场景与画面风格，即可开始文字创作。':studio.mode==='image'?`选择最多 ${studioImageReferenceLimit(studio)} 张参考图片；已有素材会保留。`:'当前视频生成支持单张图片，编辑或延长支持单段视频。其他素材可以保留整理。';toast(info);}

function setMode(mode){if(studio.mode===mode)return;checkpoint();studio.mode=mode;const choices=modelChoices().filter(m=>studioModelContract(m).supported),choice=choices.find(m=>m.platformId===studio.config.platformId)||choices[0];if(choice)studio.config=applyStudioModelChoice(studio.config,choice);else{delete studio.config.platformId;studio.config.model='';studio.config.protocol='studio';studio.config.imageAsync=false;}credentialMemory=isLocalStudioServiceTarget(studio)?'miao-local':'manual';keyMemory='';renderAll();markDirty();}
