function fitCanvas(){const rect=$('#canvas-wrap').getBoundingClientRect();const nodes=studio.nodes,minX=Math.min(...nodes.map(n=>n.x)),maxX=Math.max(...nodes.map(n=>n.x+202)),minY=Math.min(...nodes.map(n=>n.y)),maxY=Math.max(...nodes.map(n=>n.y+140));const zoom=Math.min(1.12,(rect.width-90)/(maxX-minX),(rect.height-95)/(maxY-minY));studio.viewport={zoom:Math.max(.34,zoom),x:(rect.width-(maxX-minX)*zoom)/2-minX*zoom,y:(rect.height-(maxY-minY)*zoom)/2-minY*zoom};applyViewport();markDirty()}
function zoom(factor,clientX,clientY){const v=studio.viewport,rect=$('#canvas-wrap').getBoundingClientRect(),cx=Number.isFinite(clientX)?clientX-rect.left:rect.width/2,cy=Number.isFinite(clientY)?clientY-rect.top:rect.height/2,wX=(cx-v.x)/v.zoom,wY=(cy-v.y)/v.zoom;v.zoom=Math.max(.35,Math.min(1.8,v.zoom*factor));v.x=cx-wX*v.zoom;v.y=cy-wY*v.zoom;applyViewport();markDirty()}
function undo(){if(!undoStack.length)return;const revision=studio.revision,projectRevision=studio.projectRevision;redoStack.push(clone(studio));studio=undoStack.pop();studio.revision=revision;studio.projectRevision=projectRevision;markDirty();renderAll();}
