function cycleDialogFocus(event){
 const dialog=$('#dialog');if(event.key!=='Tab'||!dialog.open)return false;
 const controls=[...dialog.querySelectorAll('button,input,select,textarea,a[href],summary,video[controls],audio[controls],[tabindex]')].filter(el=>el.tabIndex>=0&&!el.matches(':disabled')&&!el.closest('[hidden],[inert]')&&el.getClientRects().length&&getComputedStyle(el).visibility!=='hidden');
 const first=controls[0],last=controls.at(-1),active=document.activeElement;
 if(!first)return false;
 if(event.shiftKey&&(active===first||!dialog.contains(active))||!event.shiftKey&&(active===last||!dialog.contains(active))){event.preventDefault();(event.shiftKey?last:first).focus();}
 return true;
}
