 if(submitting)return;if(pendingSubmission?.attempted){toast('上次提交尚待核对，请先查询历史任务');reconcileSubmission();return;}
 const c=studio.config;if(isJimengStudio(studio)){await generateJimengConfirm();return;}if(!c.baseUrl){connectDialog();toast('先设置 API 地址与模型');return;}if(!c.model||(!studio.prompt.trim()&&!mjPromptOptional(studio))){toast('请填写提示词和模型');selectNode(!c.model?'config':'prompt');return;}
