 if(!await saveStudio())return;let referencePlan=null;if(isArkMultimodal(studio)){try{referencePlan=await call(`/api/studios/${encodeURIComponent(studio.id)}/reference-preview`);if(referencePlan.revision!==studio.revision)throw Error('项目已变化，请重新检查');}catch(e){toast(e.message);return;}}
