 const origin=new URL(c.baseUrl).origin;
 modal('确认本次生成','一次授权，仅提交一次生成请求。',`<div class="info-box"><b>服务：</b>${esc(origin)}<br><b>模型：</b>${esc(c.model)}<br><b>请求：</b>1 次${studio.mode==='image'?(isMidjourney(studio)?`，${esc(MJ_MODES[c.mjMode])} · 最多4份图片结果`:`，输出 ${Number(c.count)} 张图片`):`，${Number(c.duration)} 秒视频`}<br><b>参考估算：</b>${estimatedCost()>0?currencySymbol()+estimatedCost().toFixed(2):'未填写单价，不代表免费'}<br><b>请求编号：</b><code id="request-id">${pendingSubmission.requestId}</code></div><div class="dialog-field"><label>本次授权预算（${esc(c.currency)}，必须大于 0）</label><input id="generation-budget" type="number" min="0.01" step="0.01" placeholder="填写你同意的预算" value="${estimatedCost()>0?estimatedCost().toFixed(2):''}"></div><div class="warning-box">${isMidjourney(studio)?`操作 ${esc(MJ_MODES[c.mjMode])}${c.mjTaskId?'、原任务编号 '+esc(c.mjTaskId):''}、${['imagine','edit','modal','remix_subtle','remix_strong'].includes(c.mjMode)&&studio.prompt.trim()?'提示词、':''}${studio.references.length} 项图片或遮罩`:`提示词与 ${studio.references.length} 项参考`}将发送至上述服务；${referencePlan?'外部参考地址与平台素材编号由平台读取。':'外部图片链接将在提交后读取。'}预算只记录授权范围，实际费用以服务商账单为准。</div>${referencePlan?arkReferencePreview(referencePlan):isApimartMultimodal(studio)&&studio.references.some(r=>/^(video|audio)\//.test(r.type||''))?'<label class="dialog-check"><input id="authorize-original-media" type="checkbox"><span>确认APIMart按参考地址读取视频或音频原文件，包括其中声音；外部内容、时长和权限由平台核对。</span></label>':''}<label class="dialog-check"><input id="authorize-send" type="checkbox"><span>我授权向此服务发送提示词及所选参考素材。</span></label><label class="dialog-check"><input id="authorize-budget" type="checkbox"><span>我已核对费用，并授权在所填预算内提交本次请求。</span></label>${arkCredentialFields({studio,keyId:'generate-key',sourceId:'generate-source',manualLabel:'本次 API Key（留空使用本页临时密钥）',placeholder:'仅在当前页面内存使用'})}<p class="dialog-copy">网络状态不明时不自动重发；先按请求编号查询历史。</p>`,[{id:'cancel',label:'取消'},{id:'submit-generation',label:'授权并提交',primary:true}]);dialogKind='confirm';if(credentialMemory==='ark-local'&&isLocalArkTarget(studio)){const source=$('#generate-source');source.value='ark-local';source.dispatchEvent(new Event('change',{bubbles:true}));}
