async function reconcileSubmission(){
 const pending=pendingSubmission;if(!pending)return;
 try{await refreshJobs();const found=jobs.find(j=>j.requestId===pending.requestId);if(found){pendingSubmission=null;showJob(found);if(['queued','running'].includes(found.status))pollJob(found.id);return;}
 modal('提交结果仍待核对','尚未找到此请求编号；不会自动重新提交。',`<div class="warning-box">请求编号：${esc(pending.requestId)}。请稍后刷新历史，并核对服务商任务或账单。确认原请求没有产生任务后，才开始新的请求。</div>`,[{id:'reconcile-submit',label:'再查历史'},{id:'clear-pending',label:'已核对原请求，关闭'},{id:'close',label:'稍后处理'}]);
 }catch(e){toast(e.message);}
}
async function submitGeneration(){
 if(isJimengStudio(studio))return submitJimengGeneration();
 if(submitting||!pendingSubmission||pendingSubmission.attempted)return;
 if((pendingSubmission.referencePlan?.sendOriginalMedia||isApimartMultimodal(studio)&&studio.references.some(r=>/^(video|audio)\//.test(r.type||'')))&&!$('#authorize-original-media')?.checked){toast('请确认发送视频或音频原文件（包括声音）');return;}
 if(!$('#authorize-send')?.checked||!$('#authorize-budget')?.checked){toast('请勾选数据发送与预算授权');return;}
 const budget=Number($('#generation-budget').value);if(!Number.isFinite(budget)||budget<=0||budget<estimatedCost()){toast('预算须大于 0，且不少于已填写的价格估算');return;}
 const button=$('[data-dialog-action="submit-generation"]'),pending=pendingSubmission;button.disabled=true;submitting=true;
 const credential=readArkCredentialFields($('#dialog-body'),keyMemory);$('#generate-key').value='';
 try{
  if(!await saveStudio()){toast('项目未保存，提交已停止');return;}
  pending.attempted=true;
  activeJob=await call(`/api/studios/${encodeURIComponent(studio.id)}/generate`,json('POST',{revision:studio.revision,requestId:pending.requestId,...credential,...(pending.referencePlan?{referenceFingerprint:pending.referencePlan.fingerprint}:{}),authorization:{origin:new URL(studio.config.baseUrl).origin,model:studio.config.model,budget,currency:studio.config.currency,sendPrompt:true,sendReferences:studio.references.length>0,...(pending.referencePlan?{sendOriginalMedia:pending.referencePlan.sendOriginalMedia}:isApimartMultimodal(studio)?{sendOriginalMedia:studio.references.some(r=>/^(video|audio)\//.test(r.type||''))}:{}),requestLimit:1}}));
  pendingSubmission=null;showJob(activeJob);pollJob(activeJob.id);
 }catch(e){if(e.status&&e.status<500){pending.attempted=false;toast(e.message);}else{await reconcileSubmission();}}
 finally{credential.apiKey='';keyMemory='';submitting=false;if(button.isConnected)button.disabled=false;}
}
function canResume(job){return Boolean(job.upstreamId)&&['failed','cancelled','interrupted','awaiting_input'].includes(job.status);}
function jobResults(job){return (job.assets||[]).map(a=>`<div class="job-result">${a.type?.startsWith('image/')?`<img src="/media/${encodeURIComponent(a.id)}" alt="${esc(a.name)}">`:a.type?.startsWith('video/')?`<video controls preload="metadata" src="/media/${encodeURIComponent(a.id)}"></video>`:`<audio controls src="/media/${encodeURIComponent(a.id)}"></audio>`}<a class="download-button" href="/media/${encodeURIComponent(a.id)}" download="${esc(a.name)}">下载 ${esc(a.name)}</a></div>`).join('');}
function showJob(job){
 activeJob=job;const running=['queued','running'].includes(job.status),resume=canResume(job);
 modal('生成任务',statusLabel(job.status),`<div id="job-details" data-job-id="${esc(job.id)}" data-status="${esc(job.status)}"><b>${esc(job.input?.studio?.config?.model||studio.config.model)}</b><p id="job-message" class="dialog-copy">${esc(job.message||'正在查询')}</p>${taskProgressMarkup(job,esc,'job-progress')}${job.uncertain?'<div class="warning-box">状态待核对。请检查服务商任务与账单，避免重复提交。</div>':''}${job.upstreamId?`<p class="dialog-copy">原任务编号：<code>${esc(job.upstreamId)}</code></p>`:''}${job.mjButtons?.length?`<details><summary>平台操作按钮编号</summary>${job.mjButtons.map(b=>`<p>${esc(b.label)}<br><code style="overflow-wrap:anywhere">${esc(b.customId)}</code></p>`).join('')}</details>`:''}${jobResults(job)}${resume&&isJimengStudio(job.input?.studio)?`<p>即梦原任务剩余查询 ${job.resultQueries?.remaining??'待核对'} 次；原总预算 ${job.input.studio.config.jimeng.resultQueries.budget} ${esc(job.input.studio.config.jimeng.resultQueries.currency)}。额度用完时请到原任务页单独确认查询，再读取结果。</p><a href="/jimeng-cli.html?project=${esc(job.projectId)}" target="_blank" rel="noopener">打开即梦原任务记录</a><label class="dialog-check"><input id="jimeng-resume-consent" type="checkbox">只确认原剩余范围，不新增生成、次数或预算</label>`:resume?'<p class="dialog-copy">原任务查询地址：'+esc(job.input?.studio?.config?.baseUrl||'')+'</p>'+arkCredentialFields({studio:job.input?.studio||studio,keyId:'resume-key',sourceId:'resume-source',manualLabel:'恢复原任务查询所需 API Key',placeholder:'仅查询原任务，不再次生成'}):''}${running?'<p class="dialog-copy">停止本机查询不会撤销上游任务或费用。</p>':''}</div>`,[
 ...(running?[{id:'cancel-wait',label:'停止本机查询'}]:[]),...(resume?[{id:'resume-job',label:'恢复原任务查询',primary:true}]:[]),
 ...(job.status==='completed'&&job.assets?.length?[{id:'apply-job',label:appliedJobs.has(job.id)||job.applied||job.appliedAt?'已放入画布':'放入画布',primary:true,disabled:appliedJobs.has(job.id)||Boolean(job.applied||job.appliedAt)}]:[]),
 ...(isMidjourney(job.input?.studio)&&job.upstreamId&&['completed','awaiting_input'].includes(job.status)?[{id:'mj-continue',label:job.status==='awaiting_input'?'补充重绘遮罩':'基于此任务继续创作'}]:[]),
 {id:'reuse-job',label:'复用参数'},{id:'close',label:'关闭'}]);dialogKind='job';
}
async function applyJob(id){
 const job=activeJob?.id===id?activeJob:jobs.find(j=>j.id===id);if(!job||!studio.projectId){toast('此创作尚未关联主画布');return;}
 const button=$('[data-dialog-action="apply-job"]');if(button)button.disabled=true;
 try{const project=await call(`/api/projects/${encodeURIComponent(studio.projectId)}`);const applied=await call(`/api/studios/${encodeURIComponent(studio.id)}/jobs/${encodeURIComponent(id)}/apply`,json('POST',{revision:project.revision}));studio.projectRevision=applied.revision;appliedJobs.add(id);await refreshJobs();toast('生成结果已放入同一项目画布');if(dialogKind==='job')showJob({...job,appliedAt:new Date().toISOString()});}
 catch(e){toast(e.status===409?'画布刚有更新，请检查后重新放入':e.message);if(button?.isConnected)button.disabled=false;}
}
async function pollJob(id){
 clearTimeout(pollTimer);const studioId=studio.id;
 try{const job=await call(`/api/jobs/${encodeURIComponent(id)}`);if(studio.id!==studioId)return;activeJob=job;
 if($('#dialog').open&&dialogKind==='job'&&$('#job-details')?.dataset.jobId===id){
  if($('#job-details').dataset.status!==job.status)showJob(job);
  else{$('#job-message').textContent=job.message||'';const oldProgressText=$('#job-progress-text');$('#job-progress-container').outerHTML=taskProgressMarkup(job,esc,'job-progress');oldProgressText?.remove();}
 }
 if(['queued','running'].includes(job.status))pollTimer=setTimeout(()=>pollJob(id),1800);else{await refreshJobs();await loadAssets();}
 }catch(e){toast(`查询失败：${e.message}。可从历史恢复原任务查询。`);}
}
async function resumeJob(id){if(isJimengStudio(activeJob?.input?.studio)){if(!$('#jimeng-resume-consent')?.checked){toast('请确认此原任务的剩余查询范围');return;}try{const job=await call(`/api/studios/${encodeURIComponent(studio.id)}/jobs/${encodeURIComponent(id)}/resume`,json('POST',{credentialSource:'jimeng-local',credentialConsent:true,queryConsent:true,originalJobId:id,requestId:crypto.randomUUID()}));showJob(job);if(['queued','running'].includes(job.status))pollJob(id);}catch(error){toast(error.message);}return;}const button=$('[data-dialog-action="resume-job"]');if(button?.disabled)return;if(button)button.disabled=true;const credential=readArkCredentialFields($('#dialog-body'),keyMemory);if($('#resume-key'))$('#resume-key').value='';try{const job=await call(`/api/studios/${encodeURIComponent(studio.id)}/jobs/${encodeURIComponent(id)}/resume`,json('POST',credential));showJob(job);pollJob(id);}catch(e){toast(e.message);if(button?.isConnected)button.disabled=false;}finally{credential.apiKey='';keyMemory='';}}

async function cancelWait(id){try{await call(`/api/studios/${encodeURIComponent(studio.id)}/jobs/${encodeURIComponent(id)}/cancel`,json('POST',{}));clearTimeout(pollTimer);toast('已停止本机查询；上游任务及费用不会撤销');await pollJob(id);}catch(e){toast(e.message);}}
